import{_ as n,l as o,o as e,c as l,v as r,p as s,x as t,d as p,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"COS 方法","description":"","frontmatter":{"title":"COS 方法","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cos-method.md","filePath":"quant/cos-method.md","lastUpdated":1789023840000}'),c={name:"quant/cos-method.md"};function m(B,a,_,u,C,k){const i=o("Mermaid");return e(),l("div",null,[a[1]||(a[1]=r('<h1 id="cos-方法" tabindex="-1">COS 方法 <a class="header-anchor" href="#cos-方法" aria-label="Permalink to &quot;COS 方法&quot;">​</a></h1><div class="epigraph"><p>在一个足够宽的区间上把风险中性密度展成余弦级数，系数由特征函数直接读出；支付的余弦系数若有闭式，欧式价格就是一项指数衰减的级数。</p><footer>—— Fang and Oosterlee, A Novel Pricing Method for European Options Based on Fourier-Cosine Series Expansions, SIAM Journal on Scientific Computing, 2008</footer></div><p><a href="/quant/carr-madan">Carr–Madan</a> 用阻尼傅里叶变换加 FFT，一次给出执行价网格。Fang 与 Oosterlee 2008 年走另一条傅里叶路：先把密度限制在 \\([a,b]\\) 上，做余弦展开，展开系数是特征函数在实轴上的取样；再与支付的余弦系数做内积。短到期、深虚值时，阻尼 FFT 的振荡与 \\(\\alpha\\) 选择往往比 COS 更烦；COS 对光滑密度呈指数收敛，几十项就能到机器精度。本篇写这条级数，特征函数仍当作给定——<a href="/quant/heston">Heston</a> 的 Riccati 不在这里重推。百慕大可在每个行权日对续持密度再做一次 COS，那是 2009 年续篇，欧式核不变。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>欧式价格是 \\(e^{-rT}\\int g(x)f(x)\\,dx\\)，其中 \\(x=\\ln S_T\\)，\\(f\\) 为风险中性密度。\\(f\\) 未知，\\(\\phi(u)=\\int e^{iux}f(x)\\,dx\\) 已知。Carr–Madan 把问题放在执行价域上做傅里叶；若只关心少量 \\(K\\)，或密度在短 \\(T\\) 下接近尖峰，阻尼核的截断误差会先于特征函数误差出现。需要一种把逼近误差写成「区间截断 + 级数截断」两笔、且对解析特征函数指数收敛的格式。</p><p>余弦基在有限区间上完备，边界处是 Neumann 型：密度及其导数的周期延拓若足够光滑，系数按 \\(k^{-2}\\) 或更快下降；若 \\(f\\) 本身由 \\(\\phi\\) 决定且 \\(\\phi\\) 指数衰减，级数就是指数收敛。问题化为：如何选 \\([a,b]\\) 使截断概率可忽略，以及香草支付的余弦系数能否闭式计算。</p><h3 id="从特征函数读余弦系数" tabindex="-1">从特征函数读余弦系数 <a class="header-anchor" href="#从特征函数读余弦系数" aria-label="Permalink to &quot;从特征函数读余弦系数&quot;">​</a></h3><p>在 \\([a,b]\\) 上</p> \\[f(x)\\approx\\sum_{k=0}^{N-1}{}&#39;A_k\\cos\\Bigl(k\\pi\\frac{x-a}{b-a}\\Bigr),\\qquad A_k=\\frac{2}{b-a}\\mathrm{Re}\\Bigl\\{\\phi\\Bigl(\\frac{k\\pi}{b-a}\\Bigr)e^{-ik\\pi a/(b-a)}\\Bigr\\}, \\]<p>撇号表示 \\(k=0\\) 项乘 \\(1/2\\)。这是把傅里叶反演的实部投影到余弦上，没有阻尼参数 \\(\\alpha\\)。期权价格</p> \\[C\\approx e^{-rT}\\sum_{k=0}^{N-1}{}&#39;\\mathrm{Re}\\Bigl\\{\\phi\\Bigl(\\frac{k\\pi}{b-a}\\Bigr)e^{-ik\\pi a/(b-a)}\\Bigr\\}V_k, \\]<p>\\(V_k\\) 是 \\(g\\) 在 \\([a,b]\\) 上的余弦系数。看涨、看跌、数字的 \\(V_k\\) 均有用指数积分写成的闭式。计算量是 \\(O(N)\\) 次特征函数赋值，不是 FFT 的整条 \\(K\\) 网格；要一条微笑就对每个 \\(K\\) 换一组 \\(V_k\\)，仍然便宜，因为 \\(\\phi\\) 可缓存。</p><p><span class="marginnote">区间 \\([a,b]\\) 是方法的带宽，对应 Carr–Madan 的 \\(\\alpha\\) 与 \\(v_{\\max}\\)。Fang–Oosterlee 建议用对数价格的累积量：\\(a=c_1-L\\sqrt{c_2+\\sqrt{c_4}}\\)，\\(b=c_1+L\\sqrt{\\cdots}\\)，\\(L\\) 取 8 到 12。\\(L\\) 太小截断支付，\\(L\\) 太大余弦频率被拉疏，同样 \\(N\\) 下振荡。Heston 的累积量有闭式，应直接用，不要用蒙特卡洛去估 \\(c_1,c_2\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实现顺序：由模型累积量定 \\([a,b]\\)；在 \\(k=0,\\ldots,N-1\\) 上算 \\(\\phi(k\\pi/(b-a))\\)；对目标支付算 \\(V_k(K)\\)；点积并贴现。Black–Scholes 下 \\(\\phi\\) 是高斯，级数应在 \\(N\\sim 64\\) 内复现公式到 \\(10^{-12}\\)，这是回归测试。Heston 把同一组 \\(\\phi\\) 点换成 Riccati 解即可。</p><p>误差分解为：区间外密度质量（截断）、级数尾（\\(N\\)）、以及 \\(\\phi\\) 自身的数值误差（分支、矩爆炸）。前两笔对解析密度指数小；第三笔与 <a href="/quant/carr-madan">Carr–Madan</a> 共享，不是 COS 能修的。短到期时密度接近 Dirac，余弦要用更多项去刻画尖峰，但通常仍远少于 FFT 为压振荡所付的 \\(N=2^{12}\\)。</p><h3 id="香草系数与多执行价" tabindex="-1">香草系数与多执行价 <a class="header-anchor" href="#香草系数与多执行价" aria-label="Permalink to &quot;香草系数与多执行价&quot;">​</a></h3><p>看涨 \\(V_k\\) 涉及 \\(\\int_{\\ln K}^{b}(e^x-K)\\cos(\\omega_k(x-a))\\,dx\\)，分部积分后是 \\(e^b\\) 与 \\(K\\) 的三角/指数组合。执行价只进入 \\(V_k\\)，不进入 \\(\\phi\\) 的取样点——这与 FFT 里 \\(K\\) 网格和频率网格绑死相反。校准若要对许多 \\(K\\) 求和方误差，可一次性算 \\(\\phi\\)，再对每个 \\(K\\) 做 \\(O(N)\\) 点积。数字期权的 \\(V_k\\) 更简单，避免了对价格差分。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>余弦展开是 \\(L^2[a,b]\\) 上的正交投影。特征函数给出密度傅里叶系数在整数频率上的值；把积分区间从 \\(\\mathbb{R}\\) 换成 \\([a,b]\\)，等于忽略窗外质量，并让密度做偶延拓。支付若在 \\([a,b]\\) 上分段光滑，其系数代数衰减，与密度系数的指数衰减相乘，价格级数仍很快。这解释了为何 COS 对扩散型、仿射型模型极准，对密度带尖点或截断（如有限活动跳跃的短到期）要加大 \\(N\\)。</p><p>与 Carr–Madan 的分工：FFT 擅长「一条到期、密执行价网格、同一 \\(\\alpha\\)」；COS 擅长「少量执行价、要极高精度、短 \\(T\\)、或要把同一核嵌进百慕大倒推」。二者都不是 <a href="/quant/option-pde">PDE</a>，都不自然处理美式连续行权——连续美式仍要自由边界或 <a href="/quant/lsm-american">LSM</a>。</p><p><span class="marginnote">把 COS 说成「比 FFT 更新所以全面替代」不准确。密网格微笑、需要实数 FFT 硬件时，Carr–Madan 仍常见。COS 的优势是无阻尼参数、误差可按累积量控制、单点价格极准。校准引擎里两者都可以，不要混用两套 \\([a,b]\\) 与 \\(\\alpha\\) 却比较「哪个模型拟合更好」。</span></p>',22)),(e(),s(d,null,{default:t(()=>[h(i,{id:"mermaid-60",class:"mermaid",graph:"flowchart%20TD%0A%20%20Cum%5B%22%E7%B4%AF%E7%A7%AF%E9%87%8F%20c1%2Cc2%2Cc4%22%5D%20--%3E%20AB%5B%22%E6%88%AA%E6%96%AD%E5%8C%BA%E9%97%B4%20%5Ba%2Cb%5D%22%5D%0A%20%20Phi%5B%22%E7%89%B9%E5%BE%81%E5%87%BD%E6%95%B0%20%CF%86%22%5D%20--%3E%20Ak%5B%22%E4%BD%99%E5%BC%A6%E7%B3%BB%E6%95%B0%20A_k%22%5D%0A%20%20AB%20--%3E%20Ak%0A%20%20Pay%5B%22%E6%94%AF%E4%BB%98%20g%22%5D%20--%3E%20Vk%5B%22%E6%94%AF%E4%BB%98%E7%B3%BB%E6%95%B0%20V_k%22%5D%0A%20%20AB%20--%3E%20Vk%0A%20%20Ak%20--%3E%20Dot%5B%22%E7%82%B9%E7%A7%AF%E8%B4%B4%E7%8E%B0%22%5D%0A%20%20Vk%20--%3E%20Dot%0A%20%20Dot%20--%3E%20C%5B%22%E6%AC%A7%E5%BC%8F%E4%BB%B7%E6%A0%BC%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h3 id="百慕大倒推里的同一核" tabindex="-1">百慕大倒推里的同一核 <a class="header-anchor" href="#百慕大倒推里的同一核" aria-label="Permalink to &quot;百慕大倒推里的同一核&quot;">​</a></h3><p>Fang–Oosterlee（2009）在每个行权日把续持价值当成新的「支付」，对状态变量再做 COS，得到百慕大。关键是续持作为 \\(x\\) 的函数要投影到余弦上，执行区域用 \\(\\max(g,\\text{续持})\\) 切断，光滑性下降，指数收敛变代数收敛。这仍比二维网格便宜，但已经不是欧式那几十项机器精度。连续美式要用行权日加密外推，误差结构接近树，不是欧式 COS。随机波动要把状态扩成二维 COS 或与 <a href="/quant/adi-pde">ADI</a> 分工。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>累积量公式必须与特征函数的约定一致（\\(\\ln S\\) 还是 \\(\\ln(S/S_0)\\)，是否含 \\(rT\\)）。区间相对现货不对称时，深度实值看涨的截断会吃掉内在价值，价格系统性偏低。\\(N\\) 不是越大越好：\\(\\phi\\) 在高频上若因分支错误而乱跳，多项只是把垃圾加进去。Feller 条件违反时 Heston 的 \\(\\phi\\) 在有限 \\(u\\) 可能炸掉，COS 与 FFT 一同失败。</p><p>不要用 COS 给路径依赖亚式直接积分——除非把平均当成额外状态并有联合特征函数。不要在未做 Black–Scholes 回归时把 Heston COS 的偏差归咎于模型。引用 2008 年论文指欧式余弦核；百慕大是后续工作。</p><p><span class="marginnote">出处：Fang and Oosterlee, <em>SIAM J. Sci. Comput.</em>, 2008；百慕大见同一作者 2009 年 <em>Numerische Mathematik</em> 或 <em>SIAM J. Sci. Comput.</em> 续作。Carr and Madan, <em>JCF</em>, 1999 是对照的阻尼 FFT。Heston 特征函数见 1993 年原文。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>COS 在 \\([a,b]\\) 上用余弦展开密度，系数来自特征函数，欧式价格是与支付系数的点积。</li><li>区间由累积量确定；\\(N\\) 对光滑密度指数收敛，短到期通常仍远小于 FFT 网格。</li><li>无阻尼 \\(\\alpha\\)；执行价只进入 \\(V_k\\)，特征函数取样可在微笑上复用。</li><li>与 Carr–Madan 分工：单点高精度与短 \\(T\\) 偏 COS，密执行价网格偏 FFT。</li><li>百慕大可嵌同一核，收敛因执行切断变差；连续美式与路径依赖不是欧式 COS 的范围。</li><li>出处：Fang and Oosterlee, <em>SIAM J. Sci. Comput.</em>, 2008；对照 Carr and Madan, 1999 与 <a href="/quant/heston">Heston</a>。</li></ul>',8))])}const E=n(c,[["render",m]]);export{A as __pageData,E as default};
